hudson.tasks.Shell.command:
#!/bin/bash # shellcheck disable=SC2154 # database_psql_*, curated_datasets_s3_role, JENKINS_HOME are provided by Jenkins set -e # Bucket the in-boundary dictionary pipeline writes its dumps to. A dump URL in this bucket is read as INBOUNDARY_SOURCE_ROLE # (fixed: the global curated_datasets_s3_role may name another account's role); any other bucket is the legacy location and is # read through ${curated_datasets_s3_role}. INBOUNDARY_DUMP_BUCKET="bdc-etl-data-d0d6191" INBOUNDARY_SOURCE_ROLE="arn:aws:iam::515157839325:role/curated-datasets-s3-role"
# Source folder containing the scripts source_scripts_folder="${JENKINS_HOME}/workspace/Bash_Functions/" ls -la "$source_scripts_folder"
# Iterate through the files in the folder and source them for script_file in "$source_scripts_folder"*.sh; do chmod +x "$script_file" if [ -f "$script_file" ] && [ -x "$script_file" ]; then echo "sourcing $script_file" # shellcheck source=/dev/null source "$script_file" fi done
refuse() { echo "REFUSED: $*" >&2 exit 1 }
### Get the s3 source location for the dump archive from the build-spec.json (surrounding whitespace is stripped). ### All of this is checked before anything talks to AWS. S3_SOURCE_LOCATION=$(jq -r '(.source_dictionary_db_s3_url // "") | if type == "string" then gsub("^\\s+|\\s+$"; "") else "" end' build-spec.json) \ || refuse "cannot read source_dictionary_db_s3_url from build-spec.json" [ -n "$S3_SOURCE_LOCATION" ] || refuse "source_dictionary_db_s3_url is missing or empty in build-spec.json" s3_url_regex='^s3://([^/[:space:]]+)/([^[:space:]]+)$' [[ "$S3_SOURCE_LOCATION" =~ $s3_url_regex ]] || refuse "source_dictionary_db_s3_url is not s3://<bucket>/<key>: $S3_SOURCE_LOCATION" SOURCE_BUCKET="${BASH_REMATCH[1]}" SOURCE_KEY="${BASH_REMATCH[2]}" [[ "$SOURCE_KEY" == *.tar ]] || refuse "source_dictionary_db_s3_url key does not end in .tar: $S3_SOURCE_LOCATION"
rm -rf dictionary_db.tar temp_extract dump_files dump_toc.list
### Download the dump. The in-boundary bucket is read as INBOUNDARY_SOURCE_ROLE through a temporary AWS CLI profile: the CLI ### assumes the role itself (credentials from the instance metadata), so no credential passes through this shell, and --profile ### makes the CLI ignore any AWS_* keys in the environment. Any other bucket is the legacy path. if [ "$SOURCE_BUCKET" = "$INBOUNDARY_DUMP_BUCKET" ]; then echo "Dictionary dump source: in-boundary bucket, $S3_SOURCE_LOCATION (identity: $INBOUNDARY_SOURCE_ROLE through an AWS CLI profile)" session="$(printf '%s-%s' "${JOB_NAME:-dictionary-restore}" "${BUILD_NUMBER:-0}" | tr -c 'A-Za-z0-9+=,.@_-' '-')" [ "${#session}" -le 64 ] || session="${session: -64}" src_cfg="$(mktemp "${TMPDIR:-/tmp}/dict-source-profile.XXXXXX")" || refuse "cannot create the AWS profile file" trap 'rm -f "${src_cfg}"' EXIT chmod 600 "$src_cfg" printf '[profile dict-source]\nrole_arn = %s\ncredential_source = Ec2InstanceMetadata\nrole_session_name = %s\n' "$INBOUNDARY_SOURCE_ROLE" "$session" > "$src_cfg" download_rc=0 AWS_CONFIG_FILE="$src_cfg" aws --profile dict-source s3 cp "$S3_SOURCE_LOCATION" dictionary_db.tar || download_rc=$? rm -f "$src_cfg" [ "$download_rc" -eq 0 ] || { echo "Download of $S3_SOURCE_LOCATION as $INBOUNDARY_SOURCE_ROLE failed (exit $download_rc)" >&2; exit "$download_rc"; } else role_assumed="" if [ -n "${curated_datasets_s3_role:-}" ]; then echo "Dictionary dump source: legacy location, $S3_SOURCE_LOCATION (identity: curated_datasets_s3_role)" assume_role "${curated_datasets_s3_role}" role_assumed=1 else echo "Dictionary dump source: legacy location, $S3_SOURCE_LOCATION (identity: instance role, curated_datasets_s3_role is not set)" fi download_rc=0 aws s3 cp "$S3_SOURCE_LOCATION" dictionary_db.tar || download_rc=$? if [ -n "$role_assumed" ]; then reset_role fi [ "$download_rc" -eq 0 ] || { echo "Download of $S3_SOURCE_LOCATION failed (exit $download_rc)" >&2; exit "$download_rc"; } fi
### Check the dump before anything touches the database (pg_restore --clean drops objects). [ -s dictionary_db.tar ] || { echo "Dump check failed: the downloaded dictionary_db.tar is missing or empty" >&2; exit 1; }
# extract archive and move dump files to set workspace location called dump_files mkdir temp_extract tar -xvf dictionary_db.tar -C temp_extract || { echo "Dump check failed: dictionary_db.tar could not be extracted" >&2; exit 1; }
mkdir dump_files find temp_extract -type f -exec mv {} dump_files/ \; [ -f dump_files/toc.dat ] || { echo "Dump check failed: no toc.dat in the dump (not a pg_dump --format=d directory)" >&2; exit 1; } # Read the dump's table of contents without a database, and require the data file of every TABLE DATA entry # (<dumpId>.dat or a compressed <dumpId>.dat.*): a truncated toc.dat or a missing data file fails here, not halfway # through pg_restore --clean. pg_restore --list dump_files/ > dump_toc.list || { echo "Dump check failed: pg_restore cannot read the dump table of contents" >&2; exit 1; } missing_data_files=0 while read -r dump_id; do if ! compgen -G "dump_files/${dump_id}.dat*" > /dev/null; then echo "Dump check failed: missing data file ${dump_id}.dat for a TABLE DATA entry" >&2 missing_data_files=$((missing_data_files + 1)) fi done < <(grep -E '^[0-9]+; [0-9]+ [0-9]+ TABLE DATA ' dump_toc.list | cut -d ';' -f 1) [ "${missing_data_files}" -eq 0 ] || exit 1 echo "Dump looks like a pg_dump directory: $(find dump_files -type f | wc -l | tr -d ' ') files"
assume_role
# Fetch and extract credentials db_psql_user_secrets=$(fetch_secret "$database_psql_root_user_secret_name") conn_user=$(extract_field "$db_psql_user_secrets" "username") conn_pass=$(extract_field "$db_psql_user_secrets" "password")
# Test the connection (this command tests the connection and exits) echo "Testing connection..." PGPASSWORD="$conn_pass" psql \ --host="$database_psql_host_address" \ --port="5432" \ --username="$conn_user" \ --dbname="picsure" \ -c "\q" || { echo "Connection test failed!"; exit 1; }
echo "Connection test successful!"
# Run pg_restore using the dump files provided in the dump_files workspace directory PGPASSWORD="$(extract_field "$db_psql_user_secrets" 'password')" \ pg_restore \ --host="${database_psql_host_address}" \ --port="5432" \ --username="$(extract_field "$db_psql_user_secrets" 'username')" \ --dbname="picsure" \ --format=d \ --jobs=10 \ --clean \ --verbose \ --no-owner \ --no-privileges \ --no-tablespaces \ --no-comments \ --no-publications \ --no-subscriptions \ --no-security-labels \ --no-table-access-method \ --schema="dict" \ "dump_files/"
